head.script:
///////// 1. 변수 및 선언 영역 /////////
// 세션정보를 얻기위한 함수사용
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd"); // 오늘날짜

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.init();
        $c.cm.PanelToGroupBox(panel_Top);
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF06005.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    const YY = scwin.vCurDate.substr(0, 4);
    const YY_1 = parseInt(scwin.vCurDate.substring(0, 4), 10) - 1;
    const YY_2 = parseInt(scwin.vCurDate.substring(0, 4), 10) - 2;
    const YY_3 = parseInt(scwin.vCurDate.substring(0, 4), 10) - 3;
    const YY_4 = parseInt(scwin.vCurDate.substring(0, 4), 10) - 4;
    edt_INTIW_DD_FROM.setValue(YY + "0101");
    edt_INTIW_DD_TO.setValue(YY + "1231");
    const strCbd_SME_YN = "전체^all," + YY + "^" + YY + "," + YY_1 + "^" + YY_1 + "," + YY_2 + "^" + YY_2 + "," + YY_3 + "^" + YY_3 + "," + YY_4 + "^" + YY_4;
    cmb_PeriodTp.CBData = strCbd_SME_YN;
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        if ($c.stf.compareFromToDate2(edt_INTIW_DD_FROM, edt_INTIW_DD_TO)) {
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF06005.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF06005.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
};

/**
 * @method
 * @name btn_SDate_onclick
 * @description btn_SDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDate_onclick = function() {
    try {
        popUpCalendar2(edt_INTIW_DD_FROM);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF06005.btn_SDate_onclick" });
    }
};

/**
 * @method
 * @name btn_EDate_onclick
 * @description btn_EDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_EDate_onclick = function() {
    try {
        popUpCalendar2(edt_INTIW_DD_TO);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF06005.btn_EDate_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Excel_onclick = async function() {
    try {
        await scwin.excelDown();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF06005.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF06005.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        scwin.setDate(cmb_PeriodTp.getValue());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF06005.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnDblClick = async function(row, colid) {
    try {
        const vURL = "/lstmgt/ULDSTF06004.gfm";
        const vWinTitle = "상장유치 설적조회(코/넥)_STF06004";
        let vParam = "&" + row; // INTVIEW_METHD_CD
        let vINTIW_DD_FROM = "";
        let vINTIW_DD_TO = "";
        if (colid === "TOT_CNT") {
            vINTIW_DD_FROM = "0101";
            vINTIW_DD_TO = "1231";
        } else {
            vINTIW_DD_FROM = colid.substring(1, 3) + "01";
            if ((colid.substring(1, 3) <= 7 && colid.substring(1, 3) % 2 === '1') ||
                colid.substring(1, 3) >= '8' && colid.substring(1, 3) % 2 === '0') vINTIW_DD_TO = colid.substring(1, 3) + "31";

            else vINTIW_DD_TO = colid.substring(1, 3) + "30";
        }
        vParam += "&" + cmb_PeriodTp.getValue() + vINTIW_DD_FROM; // INTIW_DD_FROM
        vParam += "&" + cmb_PeriodTp.getValue() + vINTIW_DD_TO; // INTIW_DD_TO
        vParam += "&" + cmb_PeriodTp.getValue(); // cmb_PeriodTp

        if ($c.frame.path("/top") !== undefined) {
            $c.frame.path("/top").WinOpen("STF06004", vURL + "?" + frame.FrameID + vParam, vWinTitle, 1300, 860);
        } else {
            await $c.frame.CreateFrame("STF06004", vURL, vWinTitle, 10, 10, 1300, 860, "window", 0, 0, true);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF06005.grd_List_OnDblClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description 상장유치실적조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setDate
 * @description 면담일 연도별검색Setting
 * @param {*} pYear pYear
 * @returns {void}
 * @hidden N
 */
scwin.setDate = function(pYear) {
    if (pYear === "all") {
        edt_INTIW_DD_FROM.setValue("");
        edt_INTIW_DD_TO.setValue("");
    } else {
        edt_INTIW_DD_FROM.setValue(pYear + "0101");
        edt_INTIW_DD_TO.setValue(pYear + "1231");
    }
};

/**
 * @method
 * @name excelDown
 * @description excel Down 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDown = async function() {
    if (dts_List.getRowCount() > 0) {
        $c.stf.doLogSave("ULDSTF06004.xml", SCREN_PROCS_TP_CD_01);
        $c.data.downloadGridViewExcel(grd_List, {fileName: "상장지원 업무실적", type: "3"});
    } else {
        await $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};
